const esc = (value) => String(value).replace(/[&<>"']/g, (char) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
const money = new Intl.NumberFormat('en-IN', {style:'currency', currency:'INR', maximumFractionDigits:0});
const fmt = (value) => money.format(Math.max(0, Math.round(value || 0)));
const num = (value) => Number.isFinite(Number.parseFloat(value)) ? Number.parseFloat(value) : 0;
const pvDue = (payment, rate, years) => years <= 0 || payment <= 0 ? 0 : Math.abs(rate) < 1e-7 ? payment * years : payment * (1 + rate) * (1 - (1 / Math.pow(1 + rate, years))) / rate;

