const cta = (title,copy,primary='Get in touch',primaryPath='/contact',secondary='',secondaryPath='/insights') => `<section class="container cta-banner"><div class="cta-orb">✦</div><div class="cta-copy"><h2>${title}</h2><p>${copy}</p></div><div class="cta-actions"><a class="button button-primary" href="${primaryPath}">${primary} <span>→</span></a>${secondary?`<a class="button button-outline" href="${secondaryPath}">${secondary} <span>→</span></a>`:''}</div></section>`;
