function home() { return `<section class="hero hero-home"><div class="container hero-grid"><div class="hero-content"><p class="eyebrow">Clarity. Structure. Confidence.</p><h1>Navigate Life’s Financial Decisions with Confidence.</h1><div class="gold-rule"></div><h2 class="hero-byline">Mitali Mehta, CA, CFP®</h2><p class="hero-lead">Chartered Accountant and Personal Finance Professional helping individuals, professionals and NRIs navigate taxation, investments and financial decisions with clarity, structure and a long-term perspective.</p><div class="hero-actions"><a href="/contact" class="button button-primary">Let's Connect <span>→</span></a><a href="/services" class="button button-outline">Explore Services</a></div>${regulatory}</div><div class="hero-portrait-wrap"><div class="portrait-accent portrait-accent-one"></div><div class="portrait-accent portrait-accent-two"></div><img class="hero-portrait" src="${A('mitali-profile.png')}" alt="Mitali Mehta, personal finance professional"><div class="hero-quote">Good financial<br>decisions today<br><em>create freedom<br>tomorrow.</em></div></div></div></section><section class="container service-pillars section-pad-top">${sectionHead('A connected view of your finances','What I do','Investment execution, taxation and financial organisation — brought together so the moving pieces are easier to understand and act on.')}<div class="card-grid card-grid-3"><article class="feature-card feature-card-tall"><div class="icon-disc icon-green">↗</div><p class="card-number">01</p><h3>Investment Solutions</h3><p>Access to a range of investment solutions including mutual funds, fixed deposits, bonds, NCDs, GIFT City products and other relevant avenues.</p><a class="text-link" href="/services">Learn more <span>→</span></a></article><article class="feature-card feature-card-tall"><div class="icon-disc icon-gold">▤</div><p class="card-number">02</p><h3>Tax Planning &amp; Compliance</h3><p>Support with income tax returns, tax planning, GST registrations and GST return filings to keep your financial affairs organised and compliant.</p><a class="text-link" href="/services">Learn more <span>→</span></a></article><article class="feature-card feature-card-tall"><div class="icon-disc icon-blue">◯</div><p class="card-number">03</p><h3>Financial Organisation &amp; Professional Support</h3><p>Practical support for salaried individuals and self-employed professionals across records, cash-flow review, tax-ready documents and financial clarity.</p><a class="text-link" href="/services">Learn more <span>→</span></a></article></div></section><section class="why-section section-pad"><div class="container">${sectionHead('The Money Maze approach','Why work with me?','Financial matters rarely exist in isolation. My work is grounded in clarity, structure and a long-term perspective.')}<div class="value-grid"><div class="value-item"><span class="line-icon">✧</span><h3>Holistic perspective</h3><p>Look at the bigger picture — your goals, priorities and financial well-being.</p></div><div class="value-item"><span class="line-icon">☷</span><h3>Structured &amp; personalised</h3><p>Organise information and decisions around your actual financial situation.</p></div><div class="value-item"><span class="line-icon">◇</span><h3>Clarity over complexity</h3><p>Make important financial ideas easier to understand and apply.</p></div><div class="value-item"><span class="line-icon">♢</span><h3>Long-term relationships</h3><p>Build trust through dependable support and continuity over time.</p></div><div class="value-item"><span class="line-icon">✓</span><h3>Ethics &amp; professionalism</h3><p>Work with care, transparency and respect for regulatory requirements.</p></div></div></div></section><section class="container credentials-strip"><p class="strip-title">Professional credentials</p><div class="credential-list"><span><b>CA</b> Chartered<br>Accountant</span><span><b>CFP®</b> Certified Financial<br>Planner</span><span><b>QFPP</b> Qualified Personal<br>Finance Professional</span><span><b>LLB</b> Bachelor of<br>Laws</span><span><b>SEBI</b> Registered Mutual<br>Fund Distributor</span><span><b>NRI</b> Investment Course<br>Certification</span></div></section><section class="container triple-feature section-pad"><article class="mini-feature"><div class="mini-feature-image abstract-image"><span>✎</span></div><div><p class="eyebrow">Insights &amp; articles</p><h3>Thoughtful writing for practical money decisions.</h3><p>Articles and educational content on personal finance, taxation, retirement and investing.</p><a class="text-link" href="/insights">Explore insights <span>→</span></a></div></article><article class="mini-feature mini-feature-tinted"><div class="mini-feature-image platform-grid"><span>NEWS</span><span>CAPITAL</span><span>FINANCE</span><span>MEDIA</span></div><div><p class="eyebrow">Featured in</p><h3>Conversations that make finance more accessible.</h3><p>Television appearances, interviews and financial awareness initiatives.</p><a class="text-link" href="/media-features">View features <span>→</span></a></div></article><article class="mini-feature"><div class="stars">★★★★★</div><blockquote>“Mitali explains complex financial concepts so simply. Her guidance helped me make confident and well-informed decisions.”</blockquote><cite>— Rajiv S., Business Owner</cite><a class="text-link" href="/testimonials">Read testimonials <span>→</span></a></article></section>${cta('Let’s start a conversation','Whether you need support with investments, taxation, financial organisation or simply want greater clarity around your finances, I would be happy to connect.',"Let's Connect",'/contact','Read Insights','/insights')}`; }

function innerHero(eyebrow,title,copy,art,primary='/contact',primaryLabel='Get in touch',secondary='/services',secondaryLabel='Explore services') { const visual = art === 'page-hero-image' ? `<div class="page-hero-image"><img src="${A('mitali-profile-glasses.png')}" alt="Mitali Mehta"></div>` : `<div class="${art}" aria-hidden="true"></div>`; return `<section class="page-hero"><div class="container page-hero-grid"><div class="page-hero-copy"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><div class="gold-rule"></div><p>${copy}</p><div class="hero-actions"><a class="button button-primary" href="${primary}">${primaryLabel} <span>→</span></a><a class="button button-outline" href="${secondary}">${secondaryLabel}</a></div></div>${visual}</div></section>`; }
function about() { return `<section class="about-original-hero"><div class="container about-hero-grid"><div class="about-hero-copy"><p class="eyebrow">About</p><h1>About <em>Mitali</em></h1><p>Chartered Accountant, CFP professional, and founder of <strong>Money Maze</strong> — a practice built around thoughtful financial solutions, tax support and organised financial decision-making for individuals and professionals.</p></div><div class="about-hero-photo"><img src="${A('mitali-profile-glasses.png')}" alt="Mitali Mehta"></div></div></section><section class="about-intro-strip"><div class="container about-intro-grid"><div><p class="eyebrow">A little about me</p><h2>Finance should feel more structured, more thoughtful and easier to navigate.</h2></div><div><p>I am a finance professional with a background across personal finance, taxation and financial organisation, and the founder of Money Maze.</p><p>Over the years, I have come to value one thing deeply: most people do not need more around money — they need more structure, more context and a more organised way of looking at their finances.</p><p>That belief is what shaped Money Maze.</p><p>My work today brings together multiple parts of an individual's financial life — from investment solutions and tax-related support to financial organisation and practical money conversations.</p></div><div class="about-still-life">✤</div></div></section><section class="container about-three-col section-pad-sm"><div class="about-maze-panel"><p class="eyebrow">Why “Money Maze”?</p><h2>Because for many people, money can genuinely feel like a maze.</h2><p>There is often too much information, too many opinions, too many products, too many moving parts — and not enough clarity on what deserves attention, what can wait and how different financial pieces fit together.</p><p>Money Maze was built around the idea of making that journey feel more organised and less intimidating.</p></div><div class="credentials-card">${sectionHead('Professional background','Professional Background')}<div class="credential-rows"><div><b>CA</b><span>Chartered Accountant (CA)</span></div><div><b>CFP</b><span>Certified Financial Planner (CFP)</span></div><div><b>QFPP</b><span>Qualified Personal Finance Professional</span></div><div><b>LLB</b><span>Bachelor of Laws (LLB)</span></div></div><p>Each of these has shaped the way I look at financial matters — not as isolated tasks, but as interconnected decisions involving investments, taxes, structure, regulation and long-term priorities.</p></div><div class="capacity-card about-capacity"><span class="line-icon">♢</span><p class="eyebrow">Current professional capacity</p><h2>A SEBI-registered Mutual Fund Distributor.</h2><p>My work includes facilitating access to mutual fund solutions and supporting clients with broader financial organisation, taxation and related financial matters in a practical and structured manner.</p></div></section><section class="container about-approach section-pad-sm"><div class="about-approach-visual">✤</div><div><p class="eyebrow">How I approach my work</p><h2>Financial work is rarely one-dimensional.</h2><p>Investment choices do not exist in isolation from taxes. Tax decisions affect cash flows. Cash flows affect what is available for future goals. Existing financial commitments influence what can realistically be done next.</p><p>That is why I value a more connected and organised approach — one that looks at financial matters with context, practicality and a long-term view.</p><p>My attempt, through Money Maze, is to make these conversations and processes feel more structured, more understandable and easier to navigate over time.</p></div><div class="about-matters"><p class="eyebrow">What matters to me</p><h2>Good financial work is not just about products or paperwork.</h2><p>One of the things I value most about this profession is the opportunity to be part of meaningful financial journeys — whether that involves putting structure around finances, handling important compliance work or simply being a steady point of contact in an area that often feels overwhelming.</p><p>To me, good financial work is about trust, consistency, responsibility and bringing order to something that affects such an important part of people’s lives.</p></div></section>${cta('Looking to connect?','If you’d like to know more about my work, services or areas of focus, feel free to get in touch.','View services','/services','Contact me','/contact')}`; }
function services() { return `<section class="page-hero page-hero-services original-page-hero"><div class="container page-hero-grid"><div class="page-hero-copy"><p class="eyebrow">Services</p><h1>Thoughtful solutions.<br>Organised finances.<br><em>Stronger tomorrow.</em></h1><div class="gold-rule"></div><p>At Money Maze, I offer services across investment solutions, tax planning &amp; compliance, and financial organisation — helping individuals and professionals manage their finances with more clarity, structure and confidence.</p></div><div class="services-hero-art"><div class="paper-stack"><span>MONEY<br>MAZE</span><i></i></div><div class="plant-art">✤</div></div></div></section><section class="container service-detail-section section-pad original-services">${sectionHead('','My 3 Service Pillars','Three interconnected areas that work together to bring structure, clarity and confidence to your financial journey.')}<div class="service-detail-grid"><article class="service-detail-card service-green"><div class="icon-disc icon-green">↗</div><p class="card-number">01</p><h2>Investment Solutions</h2><p>Access a range of investment avenues aligned with your financial goals, time horizon and overall needs.</p><h4>This may include:</h4><ul><li>Mutual Funds</li><li>Fixed Deposits</li><li>Bonds</li><li>NCDs</li><li>GIFT City Products</li><li>Other relevant investment avenues</li></ul><div class="service-card-image"><img src="${A('crops/services-1.jpg')}" alt="Coins and savings"></div></article><article class="service-detail-card service-gold"><div class="icon-disc icon-gold">▤</div><p class="card-number">02</p><h2>Tax Planning &amp; Compliance</h2><p>Stay compliant and plan better with organised tax planning and timely filings.</p><h4>This includes:</h4><ul><li>Income Tax Return filing</li><li>Tax planning</li><li>GST registration</li><li>GST return support</li></ul><div class="service-card-image"><img src="${A('crops/services-2.jpg')}" alt="Tax planning documents"></div></article><article class="service-detail-card service-blue"><div class="icon-disc icon-blue">□</div><p class="card-number">03</p><h2>Financial Organisation &amp; Professional Support</h2><p>Bring more order to your financial information so decisions and compliance become simpler and more efficient.</p><h4>This may include:</h4><ul><li>Maintaining financial records / accounts</li><li>Preparing financial data for tax filings</li><li>Organising information before return filing</li><li>Basic profit &amp; loss / cash-flow visibility</li><li>Understanding available surplus for investing or future planning</li></ul><div class="service-card-image"><img src="${A('crops/services-3.jpg')}" alt="Organised financial records"></div></article></div></section><section class="process-section section-pad"><div class="container">${sectionHead('','My Approach','A simple, transparent and structured approach that keeps your financial needs at the centre.')}<div class="process-grid">${[['01','♧','Understand','I start by understanding your financial situation, goals and priorities.'],['02','⌕','Assess','I review information and assess what is in place and what may need attention.'],['03','◇','Organise & plan','We organise your financial information and create a practical plan across key areas.'],['04','✓','Implement','I help you take the necessary actions with clarity and practical timelines.'],['05','↗','Review & stay on track','We review periodically and stay aligned with your changing needs.']].map(x=>`<div class="process-step"><b>${x[0]}</b><span class="line-icon">${x[1]}</span><h3>${x[2]}</h3><p>${x[3]}</p></div>`).join('')}</div></div></section><section class="container who-grid-section section-pad">${sectionHead('','Who I Work With','My work is built primarily around individuals, professionals, families and small business owners with practical financial requirements.')}<div class="who-grid">${[['◯','Salaried individuals','Looking for support with investments, tax planning and return filing.'],['▣','Self-employed professionals','Who need help with GST, tax compliance, financial organisation and investment-related matters.'],['♧','Individuals and families','Looking to keep investments, tax responsibilities and financial records better coordinated.'],['◎','NRIs and globally connected clients','Where relevant, investment and practical support may apply.']].map((x,i)=>`<div><span class="icon-disc ${i%3===0?'icon-green':i%3===1?'icon-gold':'icon-blue'}">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div></section><div class="container">${regulatory}</div>${cta('Let\'s bring clarity and structure to your financial journey.','If you\'d like to know more about how I can support your financial needs, let\'s connect.','Get in touch','/contact','Contact me','/contact')}`; }
function articleCards() { return articles.map((a,i)=>`<article class="article-card" data-topic="${a[1].toLowerCase()}" data-search="${(a[0]+' '+a[1]+' '+a[2]).toLowerCase()}"><div class="article-image" style="background-image:url('${A(`crops/insights-${i+1}.jpg`)}');background-size:cover;background-position:center"><span></span></div><div class="article-card-body"><p class="article-topic">${a[1]}</p><h3>${a[0]}</h3><p class="article-meta">${a[2]} <span>·</span> ${a[3]}</p><a class="text-link" href="#">Read article <span>→</span></a></div></article>`).join(''); }
function insights() { return `<section class="page-hero page-hero-insights original-page-hero"><div class="container page-hero-grid"><div class="page-hero-copy"><p class="eyebrow">Insights</p><h1>Articles, explainers, publications and practical financial perspectives.</h1><div class="gold-rule"></div><p>This section brings together my written and educational work across investing, taxation, retirement, personal finance and related financial topics. It includes a mix of articles, published pieces, practical explainers and other content intended to make financial concepts easier to understand and apply.</p></div><div class="insights-hero-art"><div class="cup-art">☕</div><div class="notebook-art">Simplify.<br>Educate.<br>Empower.</div><div class="plant-art">✤</div></div></div></section><section class="container section-pad original-insights">${sectionHead('','Explore Insights By Topic')}<div class="topic-grid topic-grid-six"><button class="topic-chip is-selected" data-filter="all"><span>◈</span>1. Personal Finance &amp; Money Management<p>Practical content around money habits, surplus management, budgeting and cash-flow thinking.</p></button><button class="topic-chip" data-filter="retirement"><span>◒</span>2. Retirement Planning<p>Articles and educational pieces on retirement readiness, income, corpus planning, risk and longevity.</p></button><button class="topic-chip" data-filter="taxation"><span>▤</span>3. Taxation &amp; Compliance<p>Explainers and practical pieces on tax planning, ITR filing, GST topics and common tax questions.</p></button><button class="topic-chip" data-filter="investing"><span>↗</span>4. Investing &amp; Financial Products<p>Content on mutual funds, fixed income, market-linked products and investment principles.</p></button><button class="topic-chip" data-filter="ipo"><span>IPO</span>5. IPOs &amp; New Offerings<p>Insights and educational content on IPOs, public issues and new financial offerings.</p></button><button class="topic-chip" data-filter="special"><span>◎</span>6. Special Topics<p>NRI-related topics, GIFT City, financial behaviour, compliance updates and emerging areas.</p></button></div></section><section class="container section-pad-sm">${sectionHead('','Featured Writing & Insights','A curated collection of articles, published pieces and educational content across investing, taxation, retirement and personal finance.')}<div class="article-grid article-grid-featured">${articleCards()}</div><div class="center-action"><a class="button button-outline" href="#article-archive">View all articles <span>→</span></a></div></section><section class="container beyond-articles section-pad-sm"><div class="beyond-image"><div class="mic-art"></div><span>Conversations<br>that make money<br>more usable.</span></div><div class="beyond-copy"><p class="eyebrow">Beyond Articles</p><h2>Some financial topics are better explained through conversation.</h2><p>Where relevant, this section includes selected podcasts, audio explainers and other knowledge formats linked to the subjects covered on the website.</p><a class="button button-primary" href="/media-features">Explore podcasts &amp; audio <span>→</span></a></div><div class="beyond-list"><p class="eyebrow">What you’ll find</p><ul><li>Podcast episodes on key financial topics</li><li>Audio explainers and short insights</li><li>Practical conversations on investing, taxation and retirement</li><li>Regular updates on relevant subjects</li></ul></div></section><section id="article-archive" class="container archive-section section-pad"><div class="archive-intro"><div class="archive-count"><span class="line-icon">☷</span><strong>150+ articles<br>and growing</strong><p>A comprehensive archive of published articles and financial writing across multiple topics.</p></div><div class="archive-table-wrap"><div class="archive-toolbar"><label class="search-box"><span>⌕</span><input id="article-search" type="search" placeholder="Search articles by title, keyword or topic..."></label><select><option>All Publications</option></select><select><option>Latest first</option></select></div><div class="archive-table"><div class="archive-row archive-head"><span>Article</span><span>Topic</span><span>Publication</span><span>Date</span><span>Actions</span></div>${articles.map(a=>`<div class="archive-row article-row" data-topic="${a[1].toLowerCase()}" data-search="${(a[0]+' '+a[1]+' '+a[2]).toLowerCase()}"><span><strong>${a[0]}</strong><small>Key ideas and practical context for everyday financial decisions.</small></span><span class="tag tag-${a[4]}">${a[1]}</span><span>${a[2]}</span><span>${a[3]}</span><span><a href="#">Read English →</a><a href="#">View Gujarati</a></span></div>`).join('')}</div></div></div></section>${cta('Looking for a specific financial topic?','Browse through available insights, articles and educational content to explore topics across investing, taxation, retirement and personal finance.','Explore articles','/insights','View publications','/media-features')}`; }
function media() { return `<section class="page-hero page-hero-media original-page-hero"><div class="container page-hero-grid"><div class="page-hero-copy"><p class="eyebrow">Media &amp; Features</p><h1>MEDIA &amp; FEATURES</h1><h2 class="hero-subheadline">Sharing insights. Building awareness. Creating impact.</h2><div class="gold-rule"></div><p>Over the years, my perspectives on investing, taxation, retirement and personal finance have been featured in leading Gujarati newspapers and media platforms. These features reflect a commitment to simplify financial concepts and create meaningful awareness.</p></div><div class="media-hero-art"><div class="cup-art">☕</div><div class="paper-stack"><span>FINANCIAL<br>INSIGHTS</span><i></i></div><div class="plant-art">✤</div></div></div></section><section class="container section-pad-sm original-media">${sectionHead('','Featured In')}<div class="featured-publications"><div class="publication-logos"><span>ચિત્રલેખા<br><small>CHITRALEKHA</small></span><span>ગુજરાત સમાચાર<br><small>GUJARAT SAMACHAR</small></span></div><div class="publication-quote"><span>“</span><p>Regular articles and columns on investing, taxation, retirement planning, finance awareness and related topics. Focused on clarity, practicality and real-life relevance.</p></div></div></section><section class="container section-pad-sm">${sectionHead('','Selected Features & Articles')}<div class="article-grid media-article-grid">${articles.map((a,i)=>`<article class="article-card"><div class="article-image" style="background-image:url('${A(`crops/media-${Math.min(i+1,5)}.jpg`)}');background-size:cover;background-position:center"></div><div class="article-card-body"><p class="article-topic">${a[1]}</p><h3>${a[0]}</h3><p class="article-meta">${a[2]} <span>·</span> ${a[3]}</p><a class="text-link" href="#">Read article <span>→</span></a></div></article>`).join('')}</div><div class="center-action"><a class="button button-outline" href="/insights">View all articles <span>→</span></a></div></section><section class="container media-pair-section section-pad-sm"><article><div class="media-feature-image"><img src="${A('crops/media-6.jpg')}" alt="Media appearance microphone"></div><div><p class="eyebrow">Media appearances</p><p>Financial topics discussed across radio and digital platforms. Conversations focused on awareness, education and practical financial guidance.</p><a class="button button-outline button-small" href="#">View all appearances <span>→</span></a></div></article><article><div class="media-feature-image"><img src="${A('crops/media-7.jpg')}" alt="Talks and interviews"></div><div><p class="eyebrow">Talks &amp; interviews</p><p>Invited for talks, panel discussions and interviews on investing, taxation, retirement planning and women &amp; finance.</p><a class="button button-outline button-small" href="#">View all interviews <span>→</span></a></div></article></section><section class="recognition-section section-pad-sm"><div class="container">${sectionHead('','Recognition & Citations')}<div class="recognition-grid"><div><span class="line-icon">♧</span><p>Recognised for simplifying complex financial topics for a wider audience.</p></div><div><span class="line-icon">♩</span><p>Consistently contributing to financial literacy through accessible content.</p></div><div><span class="line-icon">♧</span><p>Trusted by readers for balanced views and actionable insights.</p></div><div><span class="line-icon">◎</span><p>Committed to creating awareness that leads to better financial decisions.</p></div></div></div></section>${cta('Looking to feature or collaborate?','For media queries, interview requests or collaboration opportunities, feel free to reach out.','Get in touch','/contact','Contact me','/contact')}`; }
function books() { return `<section class="page-hero page-hero-books original-page-hero"><div class="container page-hero-grid"><div class="page-hero-copy"><p class="eyebrow">Books</p><h1>Books</h1><h2 class="hero-subheadline">Long-form financial writing designed to make retirement planning more practical, relatable and easier to navigate.</h2><div class="gold-rule"></div><p>This page brings together my long-form writing in personal finance and retirement planning. Beginning with my first book — <em>The Second Half of Zindagi!</em> — the work reflects the same philosophy that shapes my work across articles, media and client conversations.</p></div><div class="book-hero-art"><img class="book-mockup" src="${A('crops/books-1.jpg')}" alt="The Second Half of Zindagi book"><div class="book-quote">Retirement is not the end of the road.<br><em>It is the beginning of your second innings.</em></div></div></div></section><section id="featured-book" class="container featured-book section-pad"><div class="book-photo-frame"><img src="${A('crops/books-2.jpg')}" alt="Featured book — The Second Half of Zindagi"></div><div class="featured-book-copy"><p class="eyebrow">Featured book</p><h2>The Second Half of Zindagi!</h2><h3>Your Guide to Financial Freedom, Purpose &amp; Well-being in Your Retirement</h3><p>Retirement is often reduced to a number — a corpus target, a calculator output, or a rough estimate of “how much is enough.” But the reality is far more layered than that.</p><p><em>The Second Half of Zindagi!</em> is a practical and relatable guide to retirement planning that looks beyond formulas and asks the deeper questions retirement really brings — identity, purpose, family dynamics and the emotional shift from earning to living off accumulated wealth.</p><div class="hero-actions"><a class="button button-primary" href="/contact">Explore the book <span>→</span></a><a class="button button-outline" href="/contact">Buy the book</a></div></div></section><section class="container section-pad-sm">${sectionHead('','What the book covers')}<div class="book-topics">${['Building the Financial Foundation','Designing Your Ideal Retirement','Protection First','Age-wise Planning','When Things Don’t Go According to Plan','Special Retirement Realities','Legacy and Life Beyond Money'].map((x,i)=>`<div><span class="line-icon">${['⌂','◎','✓','♧','↗','◈','✦'][i]}</span><h3>${x}</h3><p>${['Retirement readiness, setting realistic expectations and beginning with the right groundwork.','Looking beyond numbers to think about lifestyle, purpose, priorities and the second half of life.','Health insurance, emergency reserves, debt, risk management and protection.','What retirement planning looks like across different life stages.','Late starts, shortfalls, setbacks and adjustments when life moves off-script.','Women, family structures, emotional transitions and other realities.','Estate planning, financial organisation, purpose and fulfilment.'][i]}</p></div>`).join('')}</div></section><section class="container book-two-col section-pad-sm"><div class="soft-panel"><p class="eyebrow">Why I wrote this book</p><h2>Retirement planning is more holistic than a corpus number.</h2><p>Retirement is a life transition shaped by health, inflation, family responsibilities, changing routines, emotional identity, lifestyle choices, financial uncertainty and the question of what life should look like once work is no longer at the centre of it.</p></div><div class="soft-panel"><p class="eyebrow">Who this book is for</p><h2>For anyone preparing for the second half.</h2><ul class="check-list"><li>Professionals beginning to think seriously about retirement</li><li>Individuals in their 40s and 50s organising their finances</li><li>Couples preparing for the transition into retirement</li><li>Late starters who need a realistic roadmap</li><li>Families helping parents with retirement decisions</li></ul></div></section><section class="container inside-book section-pad-sm"><div class="inside-copy"><p class="eyebrow">Inside the book</p><h2>A practical guide built around real-life situations and actionable insights.</h2><ul class="check-list"><li>Story-led chapters and relatable characters</li><li>Practical frameworks and simple explanations</li><li>Real-world issues: inflation, healthcare, shortfalls and cash flow</li><li>Age-wise perspectives on changing priorities</li><li>Tools, checklists and reflective questions</li></ul></div><div class="sample-pages"><img src="${A('crops/books-3.jpg')}" alt="Sample page"><img src="${A('crops/books-4.jpg')}" alt="Sample page"><img src="${A('crops/books-5.jpg')}" alt="Sample page"></div></section>${cta('Explore the second half with greater clarity','If retirement planning feels overwhelming, the book is designed to make the subject more approachable — one idea, one decision and one chapter at a time.','Explore the book','/books','Read my insights','/insights')}`; }
function resources() { return `<section class="page-hero page-hero-resources original-page-hero"><div class="container page-hero-grid"><div class="page-hero-copy"><p class="eyebrow">Resources &amp; Calculators</p><h1>Resources &amp; Calculators</h1><h2 class="hero-subheadline">Practical tools, worksheets and financial calculators designed to help you turn ideas into action.</h2><div class="gold-rule"></div><p>Whether you are planning for retirement, reviewing your cash flow, working through a chapter of <em>The Second Half of Zindagi!</em> or simply trying to organise your finances better, this page brings together practical tools that can help you move from concept to clarity.</p><div class="hero-actions"><a class="button button-primary" href="#calculator-library">Explore calculators <span>→</span></a><a class="button button-outline" href="#checklist-library">View checklists &amp; worksheets</a></div></div><div class="resources-hero-art"><img class="resource-book-mockup" src="${A('crops/resources-1.jpg')}" alt="The Second Half of Zindagi book"><div class="qr-card">▦<small>Reading the book?<br>Tools and worksheets<br>to continue the journey.</small></div><div class="cup-art">☕</div></div></div></section><section class="container section-pad resource-companion"><div class="resource-section-label"><span>▣</span><h2>1. Using a QR code from the book? Start here.</h2></div><p>This section is designed as a practical companion to <em>The Second Half of Zindagi!</em>. Use the tools to apply the ideas from the book and strengthen your planning.</p><div class="resource-tool-grid">${[['Retirement Corpus Calculator','Estimate the corpus that may be required for your retirement based on expenses, age and inflation.','/calculators/retirement','◫'],['Retirement Expense Inflation Calculator','Understand how today’s expenses may grow over time.','#','↗'],['Retirement Bucket Planning Worksheet','Plan how to allocate across liquidity, income, stability and growth buckets.','#','◒'],['Retirement Income / Withdrawal Calculator','See how different withdrawal amounts impact your corpus.','/calculators/swp','₹'],['Emergency Fund Calculator','Estimate an appropriate emergency reserve.','#','✓'],['Net Worth & Asset Mapping Worksheet','Organise assets, liabilities and key financial information.','#','◯'],['Insurance Review Checklist','Review your protection needs in a structured way.','#','♢'],['Estate Planning Checklist','A checklist for wills, nominations and documents.','#','▤'],['Retirement Readiness Self-Assessment','Assess your financial and practical readiness.','#','☷']].map(t=>`<a class="resource-tool-card" href="${t[2]}"><span class="resource-icon">${t[3]}</span><h3>${t[0]}</h3><p>${t[1]}</p><span class="text-link">Open tool <span>→</span></span></a>`).join('')}</div></section><section class="cream-section section-pad" id="calculator-library"><div class="container resource-library-grid"><div><div class="resource-section-label"><span>▣</span><h2>2. Financial Calculators</h2></div><div class="resource-list-group"><h3>Investment &amp; Goal Calculators</h3><a href="/calculators/sip"><b>SIP Calculator</b><small>See how regular investing can grow over time.</small><span>›</span></a><a href="#"><b>Lumpsum Growth Calculator</b><small>Estimate how a one-time investment may grow.</small><span>›</span></a><a href="#"><b>Goal Planning Calculator</b><small>Work backwards from your goal and plan better.</small><span>›</span></a></div><div class="resource-list-group"><h3>Retirement &amp; Income Calculators</h3><a href="/calculators/retirement"><b>Retirement Corpus Calculator</b><small>Estimate the corpus needed for retirement.</small><span>›</span></a><a href="/calculators/swp"><b>Retirement Income / Withdrawal Calculator</b><small>Model withdrawals and see how long your corpus may last.</small><span>›</span></a></div><div class="resource-list-group"><h3>Cash Flow &amp; Protection Tools</h3><a href="/calculators/life-insurance"><b>Insurance Need Snapshot</b><small>Get a broad view of protection needs and gaps.</small><span>›</span></a></div></div><div id="checklist-library"><div class="resource-section-label"><span>☷</span><h2>3. Checklists &amp; Worksheets</h2></div><div class="resource-list-group"><h3>Retirement &amp; Family Preparedness Checklists</h3>${checklists.map(c=>`<a href="#"><b>${c[0]}</b><small>${c[1]}</small><span>↓</span></a>`).join('')}</div><div class="resource-list-group"><h3>Tax &amp; Compliance Checklists</h3><a href="#"><b>Income Tax Return Documents Checklist</b><small>Checklist of documents needed for ITR filing.</small><span>↓</span></a><a href="#"><b>GST Registration / Compliance Checklist</b><small>Understand basic documents for GST compliance.</small><span>↓</span></a></div></div></div></section><section class="container resources-note section-pad-sm"><div class="resources-note-image"><img src="${A('crops/resources-2.jpg')}" alt="Financial planning worksheets"></div><div><div class="resource-section-label"><span>▣</span><h2>4. A note on using these tools</h2></div><p>These calculators, worksheets and checklists are designed to make financial concepts easier to understand and easier to apply. Use these resources as a practical starting point for clarity and preparation.</p></div></section><section class="resources-dark-cta container"><div class="cta-orb">•••</div><div><p class="eyebrow">5. Need help putting the numbers in context?</p><p>If a calculator has raised questions, a worksheet has highlighted gaps or you would like to approach your finances in a more organised way, I’m here to help.</p></div><div class="cta-actions"><a class="button button-secondary" href="/services">Explore Services <span>→</span></a><a class="button button-outline" href="/contact">Get in touch <span>→</span></a></div></section>`; }
function testimonials() { return `<section class="simple-page-hero"><div class="container narrow-content"><p class="eyebrow">Testimonials</p><h1>What it is like to work together — in clients’ own words.</h1><div class="gold-rule"></div><p>Working with money is rarely just a transaction. It often involves ongoing decisions, sensitive questions and the need for someone dependable on the other side.</p></div></section><section class="container section-pad testimonial-layout"><div class="testimonial-feature"><div class="stars">★★★★★</div><blockquote>“Mitali explains complex financial concepts so simply. Her guidance has helped me make confident and well-informed decisions.”</blockquote><cite>— Rajiv S., Business Owner</cite></div><div class="testimonial-list"><article><div class="stars">★★★★★</div><p>“Professional, approachable and extremely knowledgeable. I truly value her holistic approach to my finances.”</p><cite>— Priya M., HR Professional</cite></article><article><div class="stars">★★★★★</div><p>“The process feels organised and calm. I know what information is needed and what the next step should be.”</p><cite>— Ananya K., Salaried Professional</cite></article><article><div class="stars">★★★★★</div><p>“Clear explanations, practical help and a dependable point of contact. That combination makes a real difference.”</p><cite>— Mehul P., Entrepreneur</cite></article></div></section><section class="sage-section section-pad"><div class="container two-column-copy"><div><p class="eyebrow">What I hope the experience reflects</p><h2>Reliability, responsiveness and care.</h2></div><div><p>Every client's need is different — some come for investment support, some for tax or GST work, some for financial documentation, and many for a mix of these over time.</p><p>Beyond technical help, I want clients to feel that their matters are being handled with care and that they have greater confidence in the decisions ahead.</p></div></div></section>${cta('Looking for support with a financial requirement?','Explore the services I offer, or get in touch directly with what you need.','Explore services','/services','Get in touch','/contact')}`; }
function contact() { return `<section class="simple-page-hero"><div class="container narrow-content"><p class="eyebrow">Get in touch</p><h1>Let’s talk about investments, taxation, financial organisation or other professional matters.</h1><div class="gold-rule"></div><p>Whether you are reaching out for a service-related query, a writing or media request, or a general professional enquiry, you can use the form below.</p></div></section><section class="container contact-layout section-pad"><div class="contact-form-card"><p class="eyebrow">Send a message</p><h2>Tell me what you need help with.</h2><div id="form-success" class="form-errors is-hidden" style="background:#eef7ec;border-color:#b3cfaa;color:#315a37">Thank you for reaching out. Your message has been noted for this preview.</div><form class="contact-form" id="preview-contact-form"><div class="form-grid"><label>Full name<input required name="name" autocomplete="name"></label><label>Email address<input required type="email" name="email" autocomplete="email"></label><label>Phone number <span>(optional)</span><input name="phone"></label><label>City <span>(optional)</span><input name="city"></label></div><label>What would you like to get in touch about?<select required name="category"><option value="">Select an enquiry type</option><option>Investment Solutions</option><option>Tax Planning</option><option>Income Tax Return Filing</option><option>GST Registration</option><option>GST Return Filing &amp; Support</option><option>Financial Organisation &amp; Professional Support</option><option>Media / Interviews / Speaking Engagements</option><option>Book / Writing / Publication Related</option><option>Other</option></select></label><label>Message<textarea required name="message" rows="6"></textarea></label><button class="button button-primary" type="submit">Send enquiry <span>→</span></button></form></div><aside class="contact-aside"><div class="contact-detail"><span class="line-icon">@</span><div><p class="eyebrow">Email</p><p>Use the form and I’ll respond with the best way to continue the conversation.</p></div></div><div class="contact-detail"><span class="line-icon">⌖</span><div><p class="eyebrow">Office</p><p>Ahmedabad, Gujarat, India</p></div></div><div class="contact-detail contact-detail-dark"><span class="line-icon">✦</span><div><p class="eyebrow">A closing note</p><p>Thank you for visiting. If your query relates to the work I do, I’ll do my best to respond as soon as possible.</p></div></div></aside></section>`; }

function calcHeader(title,eyebrow,copy,icon) { return `<section class="calculator-hero"><div class="container calculator-hero-grid"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><div class="gold-rule"></div><p>${copy}</p></div><div class="calculator-hero-mark"><span>${icon}</span><small>Indicative educational tool</small></div></div></section>`; }
function calcShell(inner) { return `<div class="container calculator-shell">${inner}</div>`; }
function input(id,label,value,type='number') { return `<label>${label}<input id="${id}" type="${type}" value="${value}" ${type==='number'?'min="0"':''}></label>`; }
function sipCalc() { return calcHeader('SIP Calculator','Investing & growth','Explore how a monthly investment may grow with a percentage increase or a fixed annual top-up.','↗')+calcShell(`<div class="calculator-intro"><p>See how a monthly investment may grow over time. Compare a percentage-based annual increase with a fixed annual top-up.</p></div><div class="calculator-tabs"><button class="calc-tab is-active" data-sip-mode="percent">SIP growth by %</button><button class="calc-tab" data-sip-mode="fixed">SIP growth by fixed amount</button></div><div class="calc-layout"><form class="calc-form panel" id="sip-form"><div class="calc-section-header"><span>1</span><div><p class="eyebrow">Enter your inputs</p><h2>Build your SIP scenario</h2></div></div><div class="field-grid">${input('sip-monthly','Monthly SIP amount',10000)}${input('sip-years','SIP duration (years)',10)}<label class="percent-only">Annual SIP growth rate (%)<input id="sip-growth-percent" type="number" min="0" value="10"></label><label class="fixed-only is-hidden">Annual SIP top-up (₹)<input id="sip-growth-fixed" type="number" min="0" value="2000"></label>${input('sip-growth-years','Growth duration (years)',5)}${input('sip-return','Expected rate of return (%)',12)}${input('sip-post-years','Investment horizon after SIP (years)',5)}</div><button class="button button-primary" type="submit">Calculate SIP <span>→</span></button><button class="button button-link" type="reset">Reset</button></form><aside class="result-card panel"><div class="calc-section-header"><span>2</span><div><p class="eyebrow">Your estimate</p><h2>Potential SIP outcome</h2></div></div><div class="result-list"><div><span>Investment duration</span><strong id="sip-duration">—</strong></div><div><span>Total investment</span><strong id="sip-invested">—</strong></div><div class="result-highlight"><span>Corpus at the end of the horizon</span><strong id="sip-corpus">₹0</strong></div></div><div class="mini-chart" id="sip-chart"><span style="height:28%"></span><span style="height:40%"></span><span style="height:48%"></span><span style="height:65%"></span><span style="height:78%"></span><span style="height:92%"></span></div><p class="disclaimer-small">Indicative estimate using the assumptions entered. Market-linked returns are not guaranteed.</p></aside></div>`); }
function lifeCalc() { const li=[['home','Home loan outstanding'],['vehicle','Vehicle loan outstanding'],['personal','Personal loan outstanding'],['education','Education loan outstanding'],['other-liability','Other liabilities, if any']]; const goals=[['higher','Children’s higher education / marriage corpus required'],['school','Children’s school education corpus required'],['parents','Support for parents or other dependents'],['other-goal','Other major financial commitments, if any']]; const res=[['existing-insurance','Existing life insurance cover'],['assets','Current investments / assets available'],['spouse','Expected support from spouse / family income or other resources']]; const stack=(arr)=>arr.map(x=>`<label>${x[1]}<span class="input-prefix"><b>₹</b><input id="life-${x[0]}" type="number" value="${x[0]==='household'?'300000':'0'}"></span></label>`).join(''); return calcHeader('Life Insurance Calculator','Protection planning','Estimate the life insurance cover your family may need after considering goals, liabilities and resources.','◈')+calcShell(`<div class="calculator-intro"><p>A life insurance policy may need to help your family manage liabilities, meet important commitments and maintain regular expenses. Use this tool as a broad starting point.</p></div><div class="calc-layout"><form class="calc-form panel" id="life-form"><div class="calc-section-header"><span>1</span><div><p class="eyebrow">Inputs</p><h2>Build your estimate</h2></div></div><details open><summary><span>1</span> Outstanding liabilities <b>⌃</b></summary><p class="helper">Include current loans or liabilities your family may need to deal with in your absence.</p><div class="field-stack">${stack(li)}</div></details><details open><summary><span>2</span> Family goals &amp; commitments <b>⌃</b></summary><p class="helper">Include major financial goals or commitments you would want provided for.</p><div class="field-stack">${stack(goals)}</div></details><details open><summary><span>3</span> Corpus for future family expenses <b>⌃</b></summary><p class="helper">Estimate the corpus your family may need to meet regular expenses over the years.</p><div class="field-stack">${stack([['household','Current annual household expenses'],['lifestyle','Current annual lifestyle expenses']])}<label>Reduction in annual expenses (%)<span class="input-prefix"><input id="life-reduction" type="number" value="0"><b>%</b></span></label><label>Years your family needs support<input id="life-years" type="number" value="20"></label><label>Expected inflation (%)<span class="input-prefix"><input id="life-inflation" type="number" value="6"><b>%</b></span></label><label>Expected return on proceeds (%)<span class="input-prefix"><input id="life-return" type="number" value="8"><b>%</b></span></label></div></details><details open><summary><span>4</span> Existing financial resources <b>⌃</b></summary><p class="helper">Only include assets realistically available to support your family’s needs.</p><div class="field-stack">${stack(res)}</div></details><button class="button button-primary" type="submit">Calculate insurance requirement <span>→</span></button><button class="button button-link" type="reset">Reset</button></form><aside class="result-card panel"><div class="calc-section-header"><span>2</span><div><p class="eyebrow">Your estimate</p><h2>Estimated life insurance requirement</h2></div></div><div class="result-list"><div><span>Total liabilities</span><strong id="life-liabilities">₹0</strong></div><div><span>Family goals &amp; commitments</span><strong id="life-goals">₹0</strong></div><div><span>Corpus for future expenses</span><strong id="life-corpus">₹0</strong></div><div><span>Total life insurance cover required</span><strong id="life-required">₹0</strong></div><div><span>Less existing financial resources</span><strong id="life-resources">− ₹0</strong></div><div class="result-highlight"><span>Additional cover you may need</span><strong id="life-additional">₹0</strong></div></div><div class="result-note"><strong>Please note</strong><p>This estimate is a broad starting point. The right cover depends on expenses, liabilities, assets, dependents and resources already available.</p><a class="button button-primary button-small" href="/contact">Get in touch</a></div><p class="disclaimer-small">For general educational and illustrative purposes only. This is not personalised advice.</p></aside></div>`); }
function retirementCalc() { return calcHeader('Retirement Corpus Calculator','Retirement planning','Estimate a retirement corpus using today’s expenses, inflation, retirement age and expected returns.','◒')+calcShell(`<div class="calculator-intro"><p>Estimate the corpus required to fund retirement living expenses by bringing today’s expenses, inflation, retirement timing and expected returns into one view.</p></div><div class="calc-layout"><form class="calc-form panel" id="retirement-form"><div class="calc-section-header"><span>1</span><div><p class="eyebrow">Enter your inputs</p><h2>Your retirement scenario</h2></div></div><div class="field-group-title">Current expenses</div><div class="field-grid">${input('ret-household','Household expenses (annual)',300000)}${input('ret-lifestyle','Lifestyle expenses (annual)',120000)}${input('ret-other','Other expenses (annual)',0)}</div><div class="field-group-title">Future expenses</div><div class="field-grid">${input('ret-current-age','Current age',35)}${input('ret-retirement-age','Retirement age',60)}${input('ret-inflation','Inflation until retirement (%)',6)}${input('ret-drop','Drop in expenses after retirement (%)',10)}</div><div class="field-group-title">Retirement corpus</div><div class="field-grid">${input('ret-life-age','Life expectancy age',85)}${input('ret-ret-inflation','Inflation during retirement (%)',6)}${input('ret-tax','Tax on investment income (%)',0)}${input('ret-return','Expected return on corpus (%)',10)}</div><button class="button button-primary" type="submit">Calculate retirement corpus <span>→</span></button><button class="button button-link" type="reset">Reset</button></form><aside class="result-card panel"><div class="calc-section-header"><span>2</span><div><p class="eyebrow">Your estimate</p><h2>Retirement corpus required</h2></div></div><div class="result-list"><div><span>Years to retirement</span><strong id="ret-years">—</strong></div><div><span>Annual expenses at retirement</span><strong id="ret-annual">—</strong></div><div><span>Years post retirement</span><strong id="ret-post-years">—</strong></div><div class="result-highlight"><span>Indicative retirement corpus</span><strong id="ret-corpus">₹0</strong></div></div><p class="disclaimer-small">This estimate uses an annuity-due approach and the assumptions entered.</p></aside></div>`); }
function swpCalc() { return calcHeader('SWP Calculator','Retirement income','Model periodic withdrawals, inflation increases and the possible life of an investment corpus.','₹')+calcShell(`<div class="calculator-intro"><p>Model how a corpus may behave when you withdraw a monthly amount and increase withdrawals each year for inflation.</p></div><div class="calc-layout"><form class="calc-form panel" id="swp-form"><div class="calc-section-header"><span>1</span><div><p class="eyebrow">Enter your inputs</p><h2>Your withdrawal scenario</h2></div></div><div class="field-grid">${input('swp-start','Start date','2026-08-01','date')}${input('swp-corpus','Corpus amount',5000000)}${input('swp-monthly','Monthly SWP amount',30000)}${input('swp-return','Expected return (%)',8)}${input('swp-inflation','Annual increase in withdrawal (%)',6)}${input('swp-years','SWP duration (years)',20)}</div><button class="button button-primary" type="submit">Calculate SWP <span>→</span></button><button class="button button-link" type="reset">Reset</button></form><aside class="result-card panel"><div class="calc-section-header"><span>2</span><div><p class="eyebrow">Your estimate</p><h2>SWP outcome</h2></div></div><div class="result-list"><div><span>Planned duration</span><strong id="swp-duration">—</strong></div><div><span>Total withdrawal</span><strong id="swp-withdrawal">—</strong></div><div><span>Closing corpus</span><strong id="swp-closing">—</strong></div><div class="result-highlight"><span>Corpus status</span><strong id="swp-status">—</strong></div></div><p class="disclaimer-small">Returns are assumed for illustration. Actual market performance, taxes and timing will affect outcomes.</p></aside></div>`); }

function calculator(path) { const slug=path.split('/').filter(Boolean).pop(); if(slug==='sip') return sipCalc(); if(slug==='life-insurance') return lifeCalc(); if(slug==='retirement') return retirementCalc(); return swpCalc(); }

function attachNav() { const btn=document.querySelector('.nav-toggle'), navEl=document.querySelector('.primary-nav'); if(!btn||!navEl)return; btn.addEventListener('click',()=>{const open=navEl.classList.toggle('is-open');btn.setAttribute('aria-expanded',open)}); navEl.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>navEl.classList.remove('is-open'))); }
function attachInsights() { const chips=document.querySelectorAll('[data-filter]'), items=document.querySelectorAll('.article-card[data-topic],.article-row[data-topic]'), search=document.getElementById('article-search'); if(!chips.length)return; let active='all'; const update=()=>{const q=(search?.value||'').toLowerCase();items.forEach(i=>i.classList.toggle('is-hidden',!(active==='all'||i.dataset.topic.includes(active))||(!!q&&!((i.dataset.search||i.textContent.toLowerCase()).includes(q)))))}; chips.forEach(c=>c.addEventListener('click',()=>{active=c.dataset.filter;chips.forEach(x=>x.classList.toggle('is-selected',x===c));update()}));search?.addEventListener('input',update); }
function val(id){return num(document.getElementById(id)?.value)}
function initCalc(path){ if(!path.startsWith('/calculators/'))return; const slug=path.split('/').pop(); if(slug==='sip') initSip(); else if(slug==='life-insurance') initLife(); else if(slug==='retirement') initRet(); else initSwp(); }
function initSip(){let mode='percent';const form=document.getElementById('sip-form'),tabs=document.querySelectorAll('[data-sip-mode]');const toggle=()=>{document.querySelectorAll('.fixed-only').forEach(x=>x.classList.toggle('is-hidden',mode!=='fixed'));document.querySelectorAll('.percent-only').forEach(x=>x.classList.toggle('is-hidden',mode!=='percent'))};const calc=()=>{const monthly=val('sip-monthly'),sy=Math.floor(val('sip-years')),gy=Math.floor(val('sip-growth-years')),py=Math.floor(val('sip-post-years')),r=val('sip-return')/100,g=val('sip-growth-percent')/100,fix=val('sip-growth-fixed'),months=(sy+py)*12,mr=Math.pow(1+r,1/12)-1;let corpus=0,invested=0;for(let m=0;m<months;m++){const yi=Math.floor(m/12);let contribution=0;if(m<sy*12){contribution=mode==='percent'?monthly*Math.pow(1+g,Math.min(yi,gy)):monthly+fix*Math.min(yi,gy);invested+=contribution}corpus=(corpus+contribution)*(1+mr)}document.getElementById('sip-duration').textContent=`${sy+py} years`;document.getElementById('sip-invested').textContent=fmt(invested);document.getElementById('sip-corpus').textContent=fmt(corpus)};tabs.forEach(t=>t.addEventListener('click',()=>{mode=t.dataset.sipMode;tabs.forEach(x=>x.classList.toggle('is-active',x===t));toggle();calc()}));form.addEventListener('submit',e=>{e.preventDefault();calc()});form.addEventListener('reset',()=>setTimeout(calc,0));toggle();calc()}
function initLife(){const form=document.getElementById('life-form');const calc=()=>{const liabilities=['home','vehicle','personal','education','other-liability'].reduce((s,i)=>s+val(`life-${i}`),0),goals=['higher','school','parents','other-goal'].reduce((s,i)=>s+val(`life-${i}`),0),expenses=(val('life-household')+val('life-lifestyle'))*(1-val('life-reduction')/100),real=(1+val('life-return')/100)/(1+val('life-inflation')/100)-1,corpus=pvDue(expenses,real,val('life-years')),resources=['existing-insurance','assets','spouse'].reduce((s,i)=>s+val(`life-${i}`),0),required=liabilities+goals+corpus;document.getElementById('life-liabilities').textContent=fmt(liabilities);document.getElementById('life-goals').textContent=fmt(goals);document.getElementById('life-corpus').textContent=fmt(corpus);document.getElementById('life-required').textContent=fmt(required);document.getElementById('life-resources').textContent=`− ${fmt(resources)}`;document.getElementById('life-additional').textContent=fmt(Math.max(0,required-resources))};form.addEventListener('submit',e=>{e.preventDefault();calc()});form.addEventListener('reset',()=>setTimeout(calc,0));calc()}
function initRet(){const form=document.getElementById('retirement-form');const calc=()=>{const expenses=val('ret-household')+val('ret-lifestyle')+val('ret-other'),age=val('ret-current-age'),ret=Math.max(age,val('ret-retirement-age')),years=ret-age,annual=expenses*Math.pow(1+val('ret-inflation')/100,years)*(1-val('ret-drop')/100),post=Math.max(0,val('ret-life-age')-ret),real=(1+(val('ret-return')/100)*(1-val('ret-tax')/100))/(1+val('ret-ret-inflation')/100)-1,corpus=pvDue(annual,real,post);document.getElementById('ret-years').textContent=`${years} years`;document.getElementById('ret-annual').textContent=fmt(annual);document.getElementById('ret-post-years').textContent=`${post} years`;document.getElementById('ret-corpus').textContent=fmt(corpus)};form.addEventListener('submit',e=>{e.preventDefault();calc()});form.addEventListener('reset',()=>setTimeout(calc,0));calc()}
function initSwp(){const form=document.getElementById('swp-form');const calc=()=>{let corpus=val('swp-corpus'),withdrawal=val('swp-monthly'),total=0,monthsFunded=0,months=Math.floor(val('swp-years')*12),mr=Math.pow(1+val('swp-return')/100,1/12)-1,inf=val('swp-inflation')/100;for(let m=0;m<months&&corpus>0;m++){if(m>0&&m%12===0)withdrawal*=1+inf;const actual=Math.min(withdrawal,corpus);corpus=Math.max(0,(corpus-actual)*(1+mr));total+=actual;monthsFunded++}document.getElementById('swp-duration').textContent=`${(monthsFunded/12).toFixed(1)} years`;document.getElementById('swp-withdrawal').textContent=fmt(total);document.getElementById('swp-closing').textContent=fmt(corpus);document.getElementById('swp-status').textContent=monthsFunded>=months?'Corpus remains':'Corpus exhausted'};form.addEventListener('submit',e=>{e.preventDefault();calc()});form.addEventListener('reset',()=>setTimeout(calc,0));calc()}

function render() {
  const raw=window.location.pathname.replace(/\/+$/,'')||'/';
  let current=raw; let content='';
  if(raw==='/') content=home(); else if(raw==='/about') content=about(); else if(raw==='/services') content=services(); else if(raw==='/insights') content=insights(); else if(raw==='/media-features') content=media(); else if(raw==='/books') content=books(); else if(raw==='/resources') content=resources(); else if(raw==='/testimonials') content=testimonials(); else if(raw==='/contact') content=contact(); else if(raw.startsWith('/calculators/')) {content=calculator(raw); current='';} else {content=home(); current='/';}
  document.getElementById('app').innerHTML=nav(current)+`<main id="main-content">${content}</main>`+footer(current);
  document.title = raw.startsWith('/calculators/') ? 'Calculator — Money Maze' : (raw==='/'?'Money Maze — Clarity today. Freedom tomorrow.':`Money Maze — ${raw.slice(1).replaceAll('-',' ')}`);
  attachNav(); attachInsights(); initCalc(raw);
  const contactForm=document.getElementById('preview-contact-form'); contactForm?.addEventListener('submit',e=>{e.preventDefault();document.getElementById('form-success').classList.remove('is-hidden');contactForm.reset()});
}
render();
